def test_basic():
    assert sum_positive_evens([1,2,3,4,5,6]) == 12
def test_negatives_and_odds_excluded():
    assert sum_positive_evens([-2,-4,1,3,5]) == -1
def test_skip_non_int():
    assert sum_positive_evens([2, "4", 4.0, None, 6, True]) == 8
def test_empty_returns_neg1():
    assert sum_positive_evens([]) == -1
def test_all_odd_returns_neg1():
    assert sum_positive_evens([1,3,5,7]) == -1

def test_simple_palindrome():
    assert is_palindrome_alnum("A man, a plan, a canal: Panama") == True
def test_not_palindrome():
    assert is_palindrome_alnum("hello world") == False
def test_punctuation_only_empty():
    assert is_palindrome_alnum("!!! ,,, ...") == True
def test_underscore_kept_palindrome():
    assert is_palindrome_alnum("a_a") == True
def test_underscore_kept_not_palindrome():
    assert is_palindrome_alnum("a_b") == False

def test_basic_flatten():
    assert flatten_and_dedupe([1,[2,3],[2,[4,1]]]) == [4,3,2,1]
def test_skip_non_int():
    assert flatten_and_dedupe([1,"a",[2,None,3.5],[True,4]]) == [4,2,1]
def test_empty():
    assert flatten_and_dedupe([]) == []
def test_deep_nesting():
    assert flatten_and_dedupe([1,[2,[3,[4,[5]]]]]) == [5,4,3,2,1]

def test_basic_shift():
    assert caesar_cipher("abc", 1) == "bcd"
def test_wrap_and_case():
    assert caesar_cipher("XYZ xyz", 3) == "ABC abc"
def test_non_alpha_unchanged():
    assert caesar_cipher("a-1!", 2) == "c-1!"
def test_negative_shift():
    assert caesar_cipher("bcd", -1) == "abc"
def test_large_shift_mod26():
    assert caesar_cipher("abc", 27) == caesar_cipher("abc", 1)
def test_decode():
    encoded = caesar_cipher("hello", 5)
    assert caesar_cipher(encoded, 5, decode=True) == "hello"
def test_decode_default_false():
    assert caesar_cipher("abc", 1, decode=False) == "bcd"

