    assert run_length_encode("aaab") == "3ab"
def test_all_singles():
    assert run_length_encode("abc") == "abc"
def test_empty():
    assert run_length_encode("") == ""
def test_mixed():
    assert run_length_encode("aabbbcccc") == "2a3b4c"
def test_single_char():
    assert run_length_encode("zzzz") == "4z"

import pytest
def test_basic():
    assert matrix_transpose([[1,2,3],[4,5,6]]) == [[1,4],[2,5],[3,6]]
def test_square():
    assert matrix_transpose([[1,2],[3,4]]) == [[1,3],[2,4]]
def test_ragged_raises():
    with pytest.raises(ValueError):
        matrix_transpose([[1,2],[3]])
