import pytest
def test_basic():
    assert moving_average([1,2,3,4,5], 2) == [1.5,2.5,3.5,4.5]
def test_window_1():
    assert moving_average([1,2,3], 1) == [1.0,2.0,3.0]
def test_rounding():
    assert moving_average([1,2,4], 3) == [round((1+2+4)/3,3)]
def test_invalid_window_zero():
    with pytest.raises(ValueError):
        moving_average([1,2,3], 0)
def test_invalid_window_too_large():
    with pytest.raises(ValueError):
        moving_average([1,2,3], 4)

def test_strict_overlap_merges():
    assert merge_intervals([[1,4],[2,5]]) == [[1,5]]
def test_boundary_touch_not_merged():
    assert merge_intervals([[1,3],[3,5]]) == [[1,3],[3,5]]
def test_empty():
    assert merge_intervals([]) == []
def test_unsorted_input():
    assert merge_intervals([[5,7],[1,3],[2,4]]) == [[1,4],[5,7]]
def test_fully_contained():
    assert merge_intervals([[1,10],[2,3]]) == [[1,10]]

def test_basic():
    assert parse_query_string("a=1&b=2&c=3") == {"a":"1","b":"2","c":"3"}
def test_repeated_key():
    assert parse_query_string("a=1&a=2&b=3") == {"a":["1","2"],"b":"3"}
def test_url_decode():
    assert parse_query_string("name=John+Doe&city=New%20York") == {"name":"John Doe","city":"New York"}
def test_decode_in_key():
    assert parse_query_string("first%20name=Jane") == {"first name":"Jane"}

import pytest
def test_basic():
    result = histogram_bucket([1,5,12,19,20,35], 10)
